import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

vws = vals["Sheet1"]
ws = wb["Sheet1"]

def is_whole_number(value):
    if isinstance(value, bool):
        return False
    if isinstance(value, int):
        return True
    if isinstance(value, float):
        return abs(value - round(value)) < 1e-9
    if isinstance(value, str):
        try:
            x = float(value)
        except ValueError:
            return False
        return abs(x - round(x)) < 1e-9
    return False

update_rows = set()
for r in range(1, 16):
    f_val = vws.cell(row=r, column=6).value
    j_val = vws.cell(row=r, column=10).value

    if isinstance(f_val, str) and f_val.strip() == "Marble Slab Creamery":
        if is_whole_number(j_val):
            update_rows.add(r)

for r in range(1, 16):
    for c in range(6, 11):  # F through J
        v = vws.cell(row=r, column=c).value

        if c == 6 and r in update_rows:
            v = "Georgia State WH"
        elif isinstance(v, str):
            v = v.strip()

        ws.cell(row=r, column=c).value = v

wb.save(OUT)

print("Updated rows:", sorted(update_rows))
print("F10:", ws["F10"].value)
print("F13:", ws["F13"].value)
